from collections import Counter

class Solution:
    def isPossibleToRearrange(self, s: str, t: str, k: int) -> bool:
        n = len(s)
        sz = n // k
        chunks_s = [s[i:i + sz] for i in range(0, n, sz)]
        chunks_t = [t[i:i + sz] for i in range(0, n, sz)]
        return Counter(chunks_s) == Counter(chunks_t)

class Solution {
public:
    bool isPossibleToRearrange(string s, string t, int k) {
        int n = s.length();
        int sz = n / k;
        unordered_map<string, int> countS, countT;
        for (int i = 0; i < n; i += sz) {
            countS[s.substr(i, sz)]++;
            countT[t.substr(i, sz)]++;
        }
        return countS == countT;
    }
};

class Solution {
    public boolean isPossibleToRearrange(String s, String t, int k) {
        int n = s.length();
        int sz = n / k;
        Map<String, Integer> countS = new HashMap<>();
        Map<String, Integer> countT = new HashMap<>();
        for (int i = 0; i < n; i += sz) {
            String subS = s.substring(i, i + sz);
            String subT = t.substring(i, i + sz);
            countS.put(subS, countS.getOrDefault(subS, 0) + 1);
            countT.put(subT, countT.getOrDefault(subT, 0) + 1);
        }
        return countS.equals(countT);
    }
}

var isPossibleToRearrange = function(s, t, k) {
    const n = s.length;
    const sz = Math.floor(n / k);
    const countS = new Map();
    const countT = new Map();
    for (let i = 0; i < n; i += sz) {
        const subS = s.slice(i, i + sz);
        const subT = t.slice(i, i + sz);
        countS.set(subS, (countS.get(subS) || 0) + 1);
        countT.set(subT, (countT.get(subT) || 0) + 1);
    }
    if (countS.size !== countT.size) return false;
    for (const [kStr, v] of countS.entries()) {
        if (countT.get(kStr) !== v) return false;
    }
    return true;
};
